<?php require_once "../config/database.php";require_once "../includes/auth.php";require_role("admin");$total=$conn->query("SELECT COUNT(*) c FROM complaints")->fetch_assoc()["c"];foreach(["Open","In Progress","Resolved"] as $x){$s=$conn->prepare("SELECT COUNT(*) c FROM complaints WHERE status=?");$s->bind_param("s",$x);$s->execute();${str_replace(" ","_",strtolower($x))}=$s->get_result()->fetch_assoc()["c"];}include "../includes/header.php";?><h2>Admin Dashboard</h2><div class="grid"><div class="card">Total<div class="stat"><?=$total?></div></div><div class="card">Open<div class="stat"><?=$open?></div></div><div class="card">In Progress<div class="stat"><?=$in_progress?></div></div><div class="card">Resolved<div class="stat"><?=$resolved?></div></div></div><a class="btn" href="complaints.php">Manage Complaints</a> <a class="btn alt" href="reports.php">Reports</a><?php include "../includes/footer.php";?>